INSERT INTO reviews (author, role, rating, text, status, created_at) VALUES
('Марина К.', 'Расшифровка биохимии крови', 5, 'Раньше я гуглила каждую цифру из анализов и только больше пугалась. С ЛабГидом за пять минут стало понятно, что реально важно, а что можно спокойно обсудить с врачом на приёме.', 'approved', '2026-07-15 12:00:00'),
('Любовь Андреевна, 64 года', 'Общий анализ крови и гормоны', 5, 'За столько лет ни один врач не удосужился объяснить мне мои анализы, вот так — понятно, подробно, по-человечески. Загрузила, прочитала, и всё встало на свои места.', 'approved', '2026-06-15 12:00:00'),
('Дмитрий С.', 'Анализ на витамины и микроэлементы', 5, 'Удобно, что сразу видно отклонения от нормы с учётом моего возраста. Сохранил расшифровку в PDF и взял с собой на приём — врач сразу понял, о чём я хочу спросить.', 'approved', '2026-05-20 12:00:00'),
('Ольга В.', 'Гормоны щитовидной железы', 4, 'Понравилось, что объясняют простым языком без медицинских терминов. Единственное — хотелось бы больше деталей по отдельным показателям, но в целом сервис реально помогает разобраться.', 'approved', '2026-05-10 12:00:00'),
('Игорь П.', 'Биохимия и липидный профиль', 5, 'Пользуюсь уже полгода, слежу за динамикой холестерина в личном кабинете. Очень удобно видеть графики и сравнивать с прошлыми анализами — мотивирует следить за здоровьем.', 'approved', '2026-04-20 12:00:00'),
('Анна Т.', 'Общий анализ мочи', 5, 'Загрузила скан анализа, через минуту получила понятную расшифровку и список вопросов для врача. Это сильно сэкономило время на приёме — врач сразу перешёл к делу.', 'approved', '2026-04-10 12:00:00');